def validate_rrp_reference(rrp: dict[str, dict]) -> None:
    """Prevent a Telegram report when the full reference RRP set differs from the connected secret."""
    missing = [sku for sku in REFERENCE_SKUS if sku not in rrp]
    if missing:
        raise RuntimeError(
            f"Нельзя отправлять отчёты: в RRP_MAP_B64 отсутствует {len(missing)} из {len(REFERENCE_SKUS)} JRL SKU: "
            + ", ".join(missing[:15])
        )
    canonical = "".join(
        f"{sku}:{float(rrp[sku]['rrp']):g}" + chr(10)
        for sku in REFERENCE_SKUS
    )
    current = hashlib.sha256(canonical.encode("ascii")).hexdigest()
    if current != REFERENCE_SHA256:
        raise RuntimeError(
            f"Нельзя отправлять отчёты: RRP_MAP_B64 не совпадает с базой РРЦ JRL "
            f"по {len(REFERENCE_SKUS)} позициям. Сверьте источник цен."
        )
    print(f"Прайс JRL подтверждён: все {len(REFERENCE_SKUS)} артикулов совпадают.", flush=True)
